package com.mg.machineelementspro;

import android.app.Activity;
import android.graphics.*;
import android.os.Bundle;
import android.view.View;
import android.widget.*;
import java.util.*;

public class BearingFamilyActivity extends Activity {
 private BearingView view; private TextView info; private BearingFamilyEngine.Spec selected;
 @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(build());}
 private View build(){ScrollView s=new ScrollView(this);s.setBackgroundColor(Color.rgb(7,13,21));LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(12),dp(14),dp(12),dp(24));s.addView(r);TextView t=txt("RULMAN AİLESİ / GERÇEKÇİ GÖRSEL",24,true,Color.WHITE);r.addView(t);r.addView(txt("Bilyalı • makaralı • iğneli • tek yönlü sprag • cam clutch",13,false,Color.rgb(148,163,184)));
  HorizontalScrollView hs=new HorizontalScrollView(this);LinearLayout chips=new LinearLayout(this);hs.addView(chips);String[] names={"Tümü","Sabit bilyalı","Açısal","Oynak makara","Konik makara","İğneli","Tek yönlü sprag","Tek yönlü iğneli","Cam clutch"};BearingFamilyEngine.Type[] types={null,BearingFamilyEngine.Type.DEEP_GROOVE,BearingFamilyEngine.Type.ANGULAR_CONTACT,BearingFamilyEngine.Type.SPHERICAL_ROLLER,BearingFamilyEngine.Type.TAPERED_ROLLER,BearingFamilyEngine.Type.NEEDLE,BearingFamilyEngine.Type.ONE_WAY_SPRAG,BearingFamilyEngine.Type.ONE_WAY_NEEDLE,BearingFamilyEngine.Type.CAM_CLUTCH};for(int i=0;i<names.length;i++){final BearingFamilyEngine.Type ty=types[i];Button b=new Button(this);b.setText(names[i]);b.setAllCaps(false);b.setOnClickListener(v->showList(chips,ty));chips.addView(b);}r.addView(hs);
  view=new BearingView();r.addView(view,new LinearLayout.LayoutParams(-1,dp(430)));info=txt("Bir rulman seçin.",14,false,Color.rgb(226,232,240));info.setPadding(dp(8),dp(10),dp(8),dp(10));r.addView(info);LinearLayout list=new LinearLayout(this);list.setId(777);list.setOrientation(LinearLayout.VERTICAL);r.addView(list);populate(list,null);return s;}
 private void showList(LinearLayout ignored,BearingFamilyEngine.Type t){LinearLayout l=findViewById(777);populate(l,t);} private void populate(LinearLayout l,BearingFamilyEngine.Type type){l.removeAllViews();for(BearingFamilyEngine.Spec sp:BearingFamilyEngine.filter(type,0,0,0,0)){Button b=new Button(this);b.setAllCaps(false);b.setText(sp.code+"  •  "+sp.name+"  •  d"+(int)sp.d+" D"+(int)sp.D+" B"+sp.B);b.setOnClickListener(v->select(sp));l.addView(b,new LinearLayout.LayoutParams(-1,dp(58)));}}
 private void select(BearingFamilyEngine.Spec s){selected=s;view.s=s;view.invalidate();String q=s.code+" — "+s.name+"\nd="+s.d+" mm   D="+s.D+" mm   B="+s.B+" mm\nC="+s.C+" N   C0="+s.C0+" N   nmax="+s.maxRpm+" rpm"+(s.torqueNm>0?"   T="+s.torqueNm+" N·m":"")+"\n"+BearingFamilyEngine.behavior(s.type);info.setText(q);}
 private TextView txt(String s,int z,boolean bold,int col){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(col);if(bold)t.setTypeface(Typeface.DEFAULT_BOLD);return t;}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
 private class BearingView extends View{Paint p=new Paint(1),tx=new Paint(1);BearingFamilyEngine.Spec s;BearingView(){super(BearingFamilyActivity.this);setLayerType(View.LAYER_TYPE_SOFTWARE,null);}protected void onDraw(Canvas c){super.onDraw(c);c.drawColor(Color.rgb(12,19,28));grid(c);float cx=getWidth()*.48f,cy=getHeight()*.53f;float R=Math.min(getWidth(),getHeight())*.31f;BearingFamilyEngine.Type t=s==null?BearingFamilyEngine.Type.DEEP_GROOVE:s.type;drawRings(c,cx,cy,R);if(t==BearingFamilyEngine.Type.NEEDLE||t==BearingFamilyEngine.Type.ONE_WAY_NEEDLE)needles(c,cx,cy,R,t==BearingFamilyEngine.Type.ONE_WAY_NEEDLE);else if(t==BearingFamilyEngine.Type.TAPERED_ROLLER)rollers(c,cx,cy,R,true);else if(t==BearingFamilyEngine.Type.SPHERICAL_ROLLER)rollers(c,cx,cy,R,false);else if(t==BearingFamilyEngine.Type.ONE_WAY_SPRAG||t==BearingFamilyEngine.Type.CAM_CLUTCH)sprags(c,cx,cy,R);else balls(c,cx,cy,R,t==BearingFamilyEngine.Type.ANGULAR_CONTACT);labels(c);}
  void grid(Canvas c){p.setColor(Color.rgb(24,35,48));p.setStrokeWidth(1);for(int x=0;x<getWidth();x+=dp(22))c.drawLine(x,0,x,getHeight(),p);for(int y=0;y<getHeight();y+=dp(22))c.drawLine(0,y,getWidth(),y,p);}void drawRings(Canvas c,float cx,float cy,float R){p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(18));p.setShader(new RadialGradient(cx-R*.2f,cy-R*.2f,R*1.3f,new int[]{Color.WHITE,Color.rgb(164,174,185),Color.rgb(63,73,86)},null,Shader.TileMode.CLAMP));c.drawCircle(cx,cy,R,p);p.setStrokeWidth(dp(10));c.drawCircle(cx,cy,R*.48f,p);p.setShader(null);p.setStyle(Paint.Style.FILL);p.setColor(Color.rgb(20,28,38));c.drawCircle(cx,cy,R*.35f,p);}void balls(Canvas c,float cx,float cy,float R,boolean angled){for(int k=0;k<12;k++){double a=k*Math.PI*2/12+(angled?.12:0);float rr=R*.73f;float x=(float)(cx+Math.cos(a)*rr),y=(float)(cy+Math.sin(a)*rr);p.setShader(new RadialGradient(x-dp(3),y-dp(3),dp(12),Color.WHITE,Color.rgb(95,105,118),Shader.TileMode.CLAMP));c.drawCircle(x,y,dp(10),p);}p.setShader(null);}void rollers(Canvas c,float cx,float cy,float R,boolean tapered){for(int k=0;k<10;k++){double a=k*Math.PI*2/10;float x=(float)(cx+Math.cos(a)*R*.72),y=(float)(cy+Math.sin(a)*R*.72);c.save();c.rotate((float)Math.toDegrees(a)+90,x,y);p.setShader(new LinearGradient(x-dp(10),y,x+dp(10),y,Color.WHITE,Color.rgb(90,100,112),Shader.TileMode.CLAMP));RectF rr=tapered?new RectF(x-dp(7),y-dp(14),x+dp(7),y+dp(14)):new RectF(x-dp(9),y-dp(13),x+dp(9),y+dp(13));c.drawRoundRect(rr,dp(4),dp(4),p);p.setShader(null);c.restore();}}void needles(Canvas c,float cx,float cy,float R,boolean clutch){for(int k=0;k<18;k++){double a=k*Math.PI*2/18;float x=(float)(cx+Math.cos(a)*R*.72),y=(float)(cy+Math.sin(a)*R*.72);c.save();c.rotate((float)Math.toDegrees(a)+90,x,y);p.setColor(clutch&&k%2==0?Color.rgb(248,180,65):Color.rgb(205,213,223));c.drawRoundRect(new RectF(x-dp(3),y-dp(14),x+dp(3),y+dp(14)),dp(3),dp(3),p);c.restore();}}void sprags(Canvas c,float cx,float cy,float R){for(int k=0;k<16;k++){double a=k*Math.PI*2/16;float x=(float)(cx+Math.cos(a)*R*.72),y=(float)(cy+Math.sin(a)*R*.72);c.save();c.rotate((float)Math.toDegrees(a)+110,x,y);Path q=new Path();q.moveTo(x-dp(5),y-dp(13));q.lineTo(x+dp(6),y-dp(7));q.lineTo(x+dp(5),y+dp(13));q.lineTo(x-dp(6),y+dp(7));q.close();p.setShader(new LinearGradient(x-dp(6),y,x+dp(6),y,Color.WHITE,Color.rgb(120,90,50),Shader.TileMode.CLAMP));c.drawPath(q,p);p.setShader(null);c.restore();}p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(4));p.setColor(Color.rgb(74,222,128));RectF rr=new RectF(cx-R*.95f,cy-R*.95f,cx+R*.95f,cy+R*.95f);c.drawArc(rr,-60,250,false,p);p.setStyle(Paint.Style.FILL);tx.setTextSize(dp(12));tx.setColor(Color.rgb(74,222,128));c.drawText("LOCK → / FREE ←",cx-R*.65f,cy-R- dp(18),tx);}void labels(Canvas c){tx.setTypeface(Typeface.DEFAULT_BOLD);tx.setTextSize(dp(12));tx.setColor(Color.rgb(125,211,252));String name=s==null?"SABİT BİLYALI RULMAN":s.code+" • "+s.name.toUpperCase(Locale.ROOT);c.drawText(name,dp(12),dp(24),tx);tx.setTextSize(dp(11));tx.setColor(Color.WHITE);if(s!=null)c.drawText("d="+s.d+"   D="+s.D+"   B="+s.B+" mm",dp(12),getHeight()-dp(18),tx);}
 }
}
